class Solution:
    def hammingWeight(self, n: int) -> int:
        count = 0
        while n != 0:
            n &= n - 1
            count += 1
        return count
```

```python
class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        answer = 0
        for num in nums:
            answer ^= num
        return answer
```

